#[derive(Debug, Clone, PartialEq, Eq)]
pub struct DeviceSpec {
    pub id: String,
    pub enabled: bool,
    pub tags: Vec<String>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum ParseDeviceError {
    EmptyInput,
    WrongFieldCount,
    InvalidId,
    InvalidEnabled,
    InvalidTag,
}

fn valid_token(value: &str) -> bool {
    !value.is_empty()
        && value
            .bytes()
            .all(|b| b.is_ascii_alphanumeric() || b == b'_' || b == b'-')
}

pub fn parse_device_spec(input: &str) -> Result<DeviceSpec, ParseDeviceError> {
    if input.trim().is_empty() {
        return Err(ParseDeviceError::EmptyInput);
    }

    let fields: Vec<&str> = input.split(',').collect();
    if fields.len() != 3 {
        return Err(ParseDeviceError::WrongFieldCount);
    }

    let id = fields[0].trim();
    if !valid_token(id) {
        return Err(ParseDeviceError::InvalidId);
    }

    let enabled_field = fields[1].trim();
    if enabled_field.contains(':') {
        return Err(ParseDeviceError::WrongFieldCount);
    }
    let enabled = match enabled_field {
        "on" => true,
        "off" => false,
        _ => return Err(ParseDeviceError::InvalidEnabled),
    };

    let tag_field = fields[2].trim();
    let tags = if tag_field.is_empty() {
        Vec::new()
    } else {
        let mut tags = Vec::new();
        for raw in tag_field.split(':') {
            let tag = raw.trim();
            if !valid_token(tag) {
                return Err(ParseDeviceError::InvalidTag);
            }
            tags.push(tag.to_owned());
        }
        tags
    };

    Ok(DeviceSpec {
        id: id.to_owned(),
        enabled,
        tags,
    })
}
